// GET /api/barcodes/2000000000206 → the medicine with that pack barcode.
import { NextResponse, type NextRequest } from "next/server";
import { normaliseScannedCode } from "@/lib/gtin";
import { createClient } from "@/lib/supabase/server";
import type { Medicine } from "@/lib/types";

export type BarcodeLookupResponse = { medicine: Medicine } | { error: string };

// RouteContext<"/api/barcodes/[gtin]"> is generated by Next.js from the folder
// name, so TypeScript knows `params` has a `gtin` string.
export async function GET(_request: NextRequest, ctx: RouteContext<"/api/barcodes/[gtin]">) {
  // Accepts anything a scanner might send (e.g. a 14-digit GTIN), as one GTIN.
  const gtin = normaliseScannedCode((await ctx.params).gtin);

  if (!gtin) {
    return NextResponse.json<BarcodeLookupResponse>(
      { error: "That doesn't look like a valid barcode. Try scanning again." },
      { status: 400 },
    );
  }

  const supabase = await createClient();
  const { data, error } = await supabase
    .from("medicine_barcodes")
    .select("medicine:medicines(*)")
    .eq("gtin", gtin)
    .maybeSingle();

  if (error) {
    console.error("barcode lookup failed:", error);
    return NextResponse.json<BarcodeLookupResponse>({ error: "Lookup failed" }, { status: 500 });
  }
  if (!data) {
    return NextResponse.json<BarcodeLookupResponse>(
      { error: `No medicine found for barcode ${gtin}` },
      { status: 404 },
    );
  }
  return NextResponse.json<BarcodeLookupResponse>({ medicine: data.medicine });
}
